from pathlib import Path
import json,html,re
from urllib.parse import quote
ROOT=Path(__file__).resolve().parent.parent
DIST=ROOT/'dist'
D=json.loads((DIST/'tools.json').read_text())
E=lambda x:html.escape(str(x),quote=True)
GROUPS=[('imagen','Imagen & textura','Deformar, mezclar, romper y volver a mirar.'),('generativo','Código & sistemas','Patrones, reglas y resultados imprevisibles.'),('3d','Crear en 3D','Modelar formas, construir escenas y probar materiales.'),('captura','Captura & escaneo','Del mundo físico al digital.'),('ia','3D con IA','Formas a partir de texto o imágenes.'),('movimiento','Movimiento & sonido','Animar, seguir, comparar y escuchar imágenes.'),('tipo','Tipografía','Escalas, jerarquías y ritmo para trabajar con texto.'),('recursos','Recursos & más datita','Referencias, materiales y lugares para seguir buscando.')]
facets=[('access','Acceso','Todos'),('roles','Función','Todas'),('environment','Entorno','Todos'),('media','Trabaja con','Todos'),('connections','Programas / formatos','Todos')]
values=lambda field:sorted({v for d in D for v in d[field]},key=lambda v:({'Gratis':0,'Freemium':1,'Pago':2}.get(v,5),v))
def filter_menu(field,label,options):
 ident=f'filter-{field}'
 rows=''.join(f'<div class="filter-option" id="{ident}-option-{i}" role="option" data-value="{E(value)}" aria-selected="{str(i==0).lower()}"><span>{E(text)}</span><span class="filter-check" aria-hidden="true">✓</span></div>' for i,(value,text) in enumerate(options))
 return f'<div class="filter-field"><span id="{ident}-label">{E(label)}</span><button type="button" class="filter-trigger" id="{ident}" data-filter="{field}" value="" role="combobox" aria-expanded="false" aria-haspopup="listbox" aria-controls="{ident}-options" aria-labelledby="{ident}-label"><span class="filter-value">{E(options[0][1])}</span><svg aria-hidden="true" viewBox="0 0 16 16" fill="none"><path d="m4 6 4 4 4-4" stroke="currentColor" stroke-width="1.2"/></svg></button><div class="filter-options" id="{ident}-options" role="listbox" aria-labelledby="{ident}-label" hidden>{rows}</div></div>'
selects=''.join(filter_menu(field,label,[('',all_label)]+[(v,v) for v in values(field)]) for field,label,all_label in facets)
selects+=filter_menu('favorites','Favoritos de Paco',[('','Todas'),('only','Solo favoritos')])
nav='<button type="button" class="category-button active" data-category="" aria-pressed="true"><span>Todas las herramientas</span><span data-count="">{{TOOL_COUNT}}</span></button>'+''.join(f'<button type="button" class="category-button" data-category="{ident}" aria-pressed="false"><span>{E(name)}</span><span data-count="{ident}">{sum(d["category"]==ident for d in D):02d}</span></button>' for ident,name,desc in GROUPS)
BAND='<div class="shader-band" aria-hidden="true"></div>'
sections=[]
for i,(ident,name,desc) in enumerate(GROUPS,1):
 cards=[]
 for d in D:
  if d['category']!=ident:continue
  img=d.get('image',{})
  label=img.get('label','Vista de la herramienta')
  picture=f'<a class="visual" href="{E(d["url"])}" target="_blank" rel="noopener noreferrer" aria-label="Abrir {E(d["name"])} en otra pestaña"><img src="{E(img.get("path",""))}" alt="{E(label)}: {E(d["name"])}" width="960" height="540" loading="lazy" decoding="async"></a>'
  if d['id'] in ['tool-001','tool-002']:picture=picture.replace('loading="lazy"','loading="eager"')
  chips=''.join(f'<button type="button" class="tag {"access-tag" if field=="access" else ""}" data-facet="{field}" data-value="{E(v)}" aria-label="Filtrar por {E(v)}" title="{E(d["price_note"] if field=="access" else "Buscar más herramientas con esta etiqueta")}">{E(v)}</button>' for field in ['access','roles','media'] for v in d[field] if field!='media' or v not in ['Código','Web'])
  connection_chips=''.join(f'<button type="button" class="tag" data-facet="connections" data-value="{E(v)}" aria-label="Filtrar por {E(v)}">{E(v)}</button>' for v in d['connections'])
  domain=d['url'].split('/')[2].replace('www.','')
  note=f'<p class="note">{E(d["note"])}</p>' if d['note'] else ''
  source_label='Imagen de fxhash' if d['name']=='LIITH / fxhash' else 'Captura · fuente' if 'screenshot' in img.get('type','') else 'Ejemplo · fuente' if 'example' in img.get('type','') else 'Imagen · fuente'
  sources=f'<div class="card-sources"><a href="{E(img.get("source_url",d["url"]))}" target="_blank" rel="noopener noreferrer" title="{E(label)}">{E(source_label)}</a><a href="{E(d["price_source"])}" target="_blank" rel="noopener noreferrer" title="{E(d["price_note"])}" aria-label="Ver condiciones de acceso de {E(d["name"])}">Ver acceso</a></div>'
  cards.append(f'<article class="card" id="{E(d["id"])}" data-tool="{E(d["id"])}">{picture}<div class="card-content"><div class="card-meta"><span><a href="{E(d["url"])}" target="_blank" rel="noopener noreferrer">{E(domain)}</a></span><span>{E(" · ".join(d["environment"]))}</span></div><h3><a href="{E(d["url"])}" target="_blank" rel="noopener noreferrer">{E(d["name"])}</a></h3><p class="description">{E(d["description"])}</p><div class="tags">{chips}{connection_chips}</div>{note}{sources}</div></article>')
  # Long titles wrap at natural boundaries, never force character overlap.
 sections.append(f'<section class="tool-section" data-section="{ident}" id="{ident}" aria-labelledby="title-{ident}">{BAND}<div class="section-heading"><div class="section-title"><span class="section-index">{i:02d}</span><h2 id="title-{ident}">{E(name)}</h2><span class="section-count" data-section-count="{ident}">{len(cards):02d}</span></div><p>{E(desc)}</p></div><div class="grid">'+''.join(cards)+'</div></section>')
FACE='''<svg class="paco-face" viewBox="0 0 8 8" shape-rendering="crispEdges" aria-hidden="true" focusable="false"><path fill="currentColor" d="M1 0h6v1H1z M0 1h8v1H0z M0 2h2v1H0z M3 2h2v1H3z M6 2h2v1H6z M0 3h8v1H0z M0 4h1v1H0z M2 4h4v1H2z M7 4h1v1H7z M0 5h2v1H0z M6 5h2v1H6z M0 6h8v1H0z M1 7h6v1H1z"/></svg>'''
favicon='<link rel="icon" type="image/svg+xml" href="data:image/svg+xml,'+quote((DIST/'paco-face.svg').read_text(),safe='')+'">'
PAGE = ('''<!DOCTYPE html><html lang="es-AR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#080808"><title>Datita digital de Paco</title><meta name="description" content="Herramientas de diseño experimental. Explorá {{TOOL_COUNT}} recursos de imagen, 3D, código y movimiento por categoría y etiquetas.">'''+favicon+'''<link rel="preload" href="fonts/satoshi-400.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="style.css"><script type="module" src="app.mjs"></script></head><body><a class="skip" href="#explorar">Ir a las herramientas</a><header class="masthead"><a class="wordmark" href="#top">datita'''+FACE+'''</a><span class="header-caption">Una colección de Paco</span><a href="#recursos" class="header-link">Más datita</a></header><main id="top"><div class="intro"><h1>Datita digital de Paco'''+FACE+'''</h1><div class="intro-copy"><p>Herramientas, recursos y pequeños hallazgos para experimentar con diseño.</p><span>{{TOOL_COUNT}} enlaces / {{CATEGORY_COUNT}} categorías</span></div></div><section class="explore" id="explorar" aria-labelledby="explore-title"><div class="explore-heading"><h2 id="explore-title">Explorar</h2><p>Una categoría. Muchas maneras de encontrar.</p></div><div class="search-row"><label class="search-field"><span class="sr-only">Buscar herramientas</span><svg aria-hidden="true" viewBox="0 0 24 24" fill="none"><circle cx="10.5" cy="10.5" r="6.5" stroke="currentColor" stroke-width="1.5"/><path d="m15.5 15.5 5 5" stroke="currentColor" stroke-width="1.5"/></svg><input type="search" id="search" placeholder="Buscar una herramienta, una técnica, una etiqueta…" autocomplete="off"></label><button type="button" class="reset-button" id="reset">Limpiar filtros</button></div><div class="filter-grid">'''+selects+'''</div><div class="search-status"><p id="result-count" role="status" aria-live="polite" aria-atomic="true">{{TOOL_COUNT}} herramientas</p><div id="active-filters" class="active-filters" aria-label="Filtros activos"></div></div><details class="tag-guide"><summary>Cómo están organizadas las etiquetas</summary><div><p><strong>Acceso:</strong> gratis, freemium (base gratis y extras de pago), pago. Describe el acceso, no la licencia comercial de los resultados.</p><p><strong>Función:</strong> generador, editor, efectos, captura, simulación, animación, código, IA, descarga, recursos, referencias, directorio y publicación.</p><p><strong>Entorno y contenido:</strong> dónde se usa y con qué se trabaja: navegador o app; imagen, video, 3D, texto, sonido y código.</p><p><strong>Programas / formatos:</strong> integraciones confirmadas, como Figma, y archivos que permiten conectar herramientas, como SVG u OBJ. Un formato compatible no implica un plugin nativo.</p><p>Podés combinar un valor de cada filtro. Última actualización de la colección: 06/10/2026. Cada ficha enlaza a sus condiciones de acceso.</p></div></details><noscript><p>Las herramientas están disponibles abajo. Activá JavaScript para usar la búsqueda y los filtros.</p></noscript></section><div class="workspace">'''+BAND+'''<aside class="index"><p class="index-label">CATEGORÍAS</p><nav aria-label="Filtrar por categoría">'''+nav+'''</nav></aside><div class="collection" id="collection">'''+BAND+'''<div class="empty" id="empty-state" hidden><h2>No encontramos esa combinación.</h2><p>Probá otra palabra o quitá alguno de los filtros.</p><button type="button" data-reset>Ver todas las herramientas</button></div>'''+''.join(sections)+'''</div></div><footer><span>Datita digital de Paco'''+FACE+'''</span><p>Herramientas ajenas. Curiosidad propia.</p><a href="#top">Volver arriba</a><span class="font-credit">Satoshi por <a href="https://www.fontshare.com/fonts/satoshi" target="_blank" rel="noopener noreferrer">Fontshare</a></span></footer></main><script id="tools-data" type="application/json">'''+json.dumps(D,ensure_ascii=False).replace('<','\\u003c')+'''</script></body></html>''')
(DIST/'index.html').write_text(PAGE.replace('{{TOOL_COUNT}}',str(len(D))).replace('{{CATEGORY_COUNT}}',str(len(GROUPS))))
print(f'{len(D)} fichas generadas')
